今天是2026年1月26日，是代码随想录的第十三天，主要学习二叉树的相关知识。
题目及卡哥解析
深度优先
144.二叉树的前序遍历
145.二叉树的后序遍历
94.二叉树的中序遍历


广度优先
102.二叉树的层序遍历
107.二叉树的层次遍历II
199.二叉树的右视图
637.二叉树的层平均值
429.N叉树的层序遍历
515.在每个树行中找最大值
116.填充每个节点的下一个右侧节点指针
117.填充每个节点的下一个右侧节点指针II
104.二叉树的最大深度
111.二叉树的最小深度



题目解析144. 二叉树的前序遍历 这边有两种解法，一是递归，二是迭代。递归比较简单，直接按照前序遍历的顺序进行递归即可。迭代的话，我们可以使用栈来模拟递归的过程，先将根节点入栈，然后每次弹出栈顶节点，访问该节点，并将其右子节点和左子节点依次入栈。
class Solution &#123;public:    // 递归法    // void frontore(TreeNode *node, vector&lt;int&gt;&amp; res)      // &#123;    //     if(node == nullptr)    //         return;    //     res.push_back(node-&gt;val);    //     frontore(node-&gt;left, res);    //     frontore(node-&gt;right, res);    // &#125;    // vector&lt;int&gt; preorderTraversal(TreeNode* root) &#123;    //     vector&lt;int&gt; res;    //     frontore(root, res);    //     return res;    // &#125;    // 迭代法    vector&lt;int&gt; preorderTraversal(TreeNode* root)    &#123;        stack&lt;TreeNode*&gt; stk;        vector&lt;int&gt; res;        if(root != nullptr)            stk.push(root);        while(!stk.empty())        &#123;            TreeNode* node = stk.top();            stk.pop();            res.push_back(node-&gt;val);            if(node-&gt;right != nullptr)                stk.push(node-&gt;right);            if(node-&gt;left != nullptr)                stk.push(node-&gt;left);        &#125;        return res;    &#125;&#125;;


145. 二叉树的后序遍历和上一道题目相同，我们也可以使用递归和迭代两种方法来实现后序遍历。递归方法直接按照后序遍历的顺序进行递归即可。迭代方法可以使用两个栈来实现，先将根节点入栈，然后每次弹出栈顶节点，访问该节点，并将其左子节点和右子节点依次入栈。最后将结果反转即可。
class Solution &#123;public:    // void postore(TreeNode *node, vector&lt;int&gt;&amp; res)    // &#123;    //     if(node == nullptr)    //         return;    //     postore(node-&gt;left, res);    //     postore(node-&gt;right, res);    //     res.push_back(node-&gt;val);    // &#125;    // vector&lt;int&gt; postorderTraversal(TreeNode* root) &#123;    //     vector&lt;int&gt; res;    //     postore(root, res);    //     return res;    // &#125;    vector&lt;int&gt; postorderTraversal(TreeNode* root) &#123;        stack&lt;TreeNode*&gt; stk;        vector&lt;int&gt; res;        if(root != nullptr)            stk.push(root);        while(!stk.empty())        &#123;            TreeNode *node = stk.top();            stk.pop();            res.push_back(node-&gt;val);            if(node-&gt;left != nullptr)                stk.push(node-&gt;left);            if(node-&gt;right != nullptr)                stk.push(node-&gt;right);        &#125;        reverse(res.begin(), res.end());        return res;    &#125;&#125;;


94. 二叉树的中序遍历同样的，我们也可以使用递归和迭代两种方法来实现中序遍历。递归方法直接按照中序遍历的顺序进行递归即可。迭代方法可以使用栈来模拟递归的过程，先将根节点入栈，然后不断将左子节点入栈，直到左子节点为空，然后弹出栈顶节点，访问该节点，并将其右子节点入栈。
class Solution &#123;public:    // void inore(TreeNode *node, vector&lt;int&gt;&amp; res)    // &#123;    //     if(node == nullptr)    //         return;    //     inore(node-&gt;left, res);    //     res.push_back(node-&gt;val);    //     inore(node-&gt;right, res);    // &#125;    // vector&lt;int&gt; inorderTraversal(TreeNode* root) &#123;    //     vector&lt;int&gt; res;    //     inore(root, res);    //     return res;    // &#125;    vector&lt;int&gt; inorderTraversal(TreeNode* root) &#123;        vector&lt;int&gt; res;        stack&lt;TreeNode*&gt; stk;        if(root != nullptr)            stk.push(root);        while(!stk.empty())        &#123;            TreeNode* node = stk.top();            if(node != nullptr)            &#123;                stk.pop();                if(node-&gt;right != nullptr)                    stk.push(node-&gt;right);                stk.push(node);                stk.push(nullptr); // 标记                if(node-&gt;left != nullptr)                    stk.push(node-&gt;left);            &#125;            else            &#123;                stk.pop(); // 弹出标记                node = stk.top();                stk.pop();                res.push_back(node-&gt;val);            &#125;        &#125;        return res;    &#125;&#125;;

接下来是广度优先的打十个102. 二叉树的层序遍历这道题目可以使用队列来实现层序遍历。首先将根节点入队，然后不断从队列中取出节点，访问该节点，并将其左子节点和右子节点依次入队。每次处理完一层节点后，将该层的结果加入到最终结果中。
class Solution &#123;public:    vector&lt;vector&lt;int&gt;&gt; levelOrder(TreeNode* root) &#123;        queue&lt;TreeNode*&gt; q;        vector&lt;vector&lt;int&gt;&gt; res;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            vector&lt;int&gt; level;            for (int i = 0; i &lt; size; ++i)            &#123;                TreeNode* node = q.front();                q.pop();                level.push_back(node-&gt;val);                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;            res.push_back(level);        &#125;        return res;    &#125;&#125;;


107. 二叉树的层次遍历II这道题目和上一道题目类似，只不过需要将结果反转一下。我们可以先按照层序遍历的方式将结果存储下来，然后再将结果反转即可。
class Solution &#123;public:    vector&lt;vector&lt;int&gt;&gt; levelOrderBottom(TreeNode* root) &#123;        queue&lt;TreeNode*&gt; q;        vector&lt;vector&lt;int&gt;&gt; res;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            vector&lt;int&gt; level;            for (int i = 0; i &lt; size; ++i)            &#123;                TreeNode* node = q.front();                q.pop();                level.push_back(node-&gt;val);                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;            res.push_back(level);        &#125;        reverse(res.begin(), res.end());        return res;    &#125;&#125;;


199. 二叉树的右视图这道题目可以使用层序遍历的方法来实现。我们在每一层遍历时，只需要记录该层的最后一个节点即可。最后将这些节点的值存储到结果中即可。
class Solution &#123;public:    vector&lt;int&gt; rightSideView(TreeNode* root) &#123;        queue&lt;TreeNode*&gt; q;        vector&lt;int&gt; res;        if (root) q.push(root);        while (!q.empty())        &#123;            int size = q.size();            for (int i = 0; i &lt; size; ++i)            &#123;                TreeNode* node = q.front();                q.pop();                if (i == size - 1)                    res.push_back(node-&gt;val);                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;        &#125;        return res;    &#125;&#125;;


637. 二叉树的层平均值这道题目同样可以使用层序遍历的方法来实现。我们在每一层遍历时，计算该层节点值的和以及节点的数量，最后将该层的平均值存储到结果中即可。
class Solution &#123;public:    vector&lt;double&gt; averageOfLevels(TreeNode* root) &#123;        queue&lt;TreeNode*&gt; q;        vector&lt;double&gt; res;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            double sum = 0;            for (int i = 0; i &lt; size; ++i)            &#123;                TreeNode* node = q.front();                q.pop();                sum += node-&gt;val;                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;            res.push_back(sum / size);        &#125;        return res;    &#125;&#125;;


429. N叉树的层序遍历这道题目和二叉树的层序遍历类似，只不过需要处理N叉树。我们同样可以使用队列来实现层序遍历。首先将根节点入队，然后不断从队列中取出节点，访问该节点，并将其所有子节点依次入队。每次处理完一层节点后，将该层的结果加入到最终结果中。
class Solution &#123;public:    vector&lt;vector&lt;int&gt;&gt; levelOrder(Node* root) &#123;        queue&lt;Node*&gt; q;        vector&lt;vector&lt;int&gt;&gt; res;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            vector&lt;int&gt; level;            for (int i = 0; i &lt; size; ++i)            &#123;                Node* node = q.front();                q.pop();                level.push_back(node-&gt;val);                for (Node* child : node-&gt;children)                &#123;                    if (child) q.push(child);                &#125;            &#125;            res.push_back(level);        &#125;        return res;    &#125;&#125;;


515. 在每个树行中找最大值这道题目同样可以使用层序遍历的方法来实现。我们在每一层遍历时，记录该层节点值的最大值，最后将这些最大值存储到结果中即可。
class Solution &#123;public:    vector&lt;int&gt; largestValues(TreeNode* root) &#123;        queue&lt;TreeNode*&gt; q;        vector&lt;int&gt; res;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            int maxVal = INT_MIN;            for (int i = 0; i &lt; size; ++i)            &#123;                TreeNode* node = q.front();                q.pop();                maxVal = max(maxVal, node-&gt;val);                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;            res.push_back(maxVal);        &#125;        return res;    &#125;&#125;;


116. 填充每个节点的下一个右侧节点指针这道题目可以使用层序遍历的方法来实现。我们在每一层遍历时，将当前节点的下一个指针指向该层的下一个节点。最后返回根节点即可。
class Solution &#123;public:    Node* connect(Node* root) &#123;        queue&lt;Node*&gt; q;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            Node* prev = nullptr;            for (int i = 0; i &lt; size; ++i)            &#123;                Node* node = q.front();                q.pop();                if (prev) prev-&gt;next = node;                prev = node;                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;        &#125;        return root;    &#125;&#125;;


117. 填充每个节点的下一个右侧节点指针II这道题目和上一道题目类似，只不过需要处理不完全二叉树。我们同样可以使用层序遍历的方法来实现。我们在每一层遍历时，将当前节点的下一个指针指向该层的下一个节点。最后返回根节点即可。
class Solution &#123;public:    Node* connect(Node* root) &#123;        queue&lt;Node*&gt; q;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            Node* prev = nullptr;            for (int i = 0; i &lt; size; ++i)            &#123;                Node* node = q.front();                q.pop();                if (prev) prev-&gt;next = node;                prev = node;                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;        &#125;        return root;    &#125;&#125;;


104. 二叉树的最大深度这道题目方法类似，只需要记录每一层的深度，最后返回最大深度即可。
class Solution &#123;public:    int maxDepth(TreeNode* root) &#123;        queue&lt;TreeNode*&gt; q;        int depth = 0;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            for (int i = 0; i &lt; size; ++i)            &#123;                TreeNode* node = q.front();                q.pop();                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;            depth++;        &#125;        return depth;    &#125;&#125;;


111. 二叉树的最小深度这道题目同样可以使用层序遍历的方法来实现。只要两个都是空节点，我们就找到了最小深度，返回当前深度即可。
class Solution &#123;public:    int minDepth(TreeNode* root) &#123;        queue&lt;TreeNode*&gt; q;        int depth = 0;        if (root) q.push(root);        while(!q.empty())        &#123;            int size = q.size();            depth++;            for (int i = 0; i &lt; size; ++i)            &#123;                TreeNode* node = q.front();                q.pop();                if (!node-&gt;left &amp;&amp; !node-&gt;right)                    return depth;                if (node-&gt;left) q.push(node-&gt;left);                if (node-&gt;right) q.push(node-&gt;right);            &#125;        &#125;        return depth;    &#125;&#125;;
